<?php namespace App\Http\Controllers; use Illuminate\Http\Request; class ProfileController extends Controller { public function edit(Request $r){return view('profile.edit',['user'=>$r->user()]);} public function update(Request $r){$u=$r->user();$d=$r->validate(['first_name'=>'required|string|max:50','middle_initial'=>'nullable|string|max:2','last_name'=>'required|string|max:50','company'=>'nullable|string|max:100','mobile_number'=>'nullable|string|max:20','email'=>'required|email|unique:users,email,'.$u->id,'job_desc'=>'nullable|string|max:100']);$u->update($d);return back()->with('success','Profile updated.');} public function password(Request $r){$d=$r->validate(['current_password'=>'required|current_password','password'=>'required|string|min:10|confirmed']);$r->user()->update(['password'=>$d['password']]);return back()->with('success','Password changed.');} }